'use strict';
const app=document.querySelector('#app');
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={catalog:null,cart:new Map(),coupon:'',quote:null,affiliate:'',order:null,token:'',tab:'orders',admin:null,goaffproPreview:null,affiliateProfile:null,profileSlug:'',profileToken:'',customer:null,customerAdmin:null,points:0,migrationPreview:null,setupId:'',setupToken:'',orderSearch:'',orderStatus:'all',orderMode:'all'};
let toastTimer;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',5000)}
async function api(path,data,token){const opts={headers:{}};if(data!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}if(token)opts.headers['X-Order-Token']=token;opts.headers['X-Store-Request']='1';const r=await fetch('/.netlify/functions/store-next?route='+encodeURIComponent(path.replace(/^\/api/,'')),opts);const result=await r.json();if(!r.ok)throw new Error(result.error||'Request failed');return result}
const button=(label,action,cls='')=>`<button type="button" data-action="${action}" class="${cls}">${label}</button>`;
function cartData(){return{items:Array.from(state.cart,([id,quantity])=>({id,quantity})),coupon:state.coupon,affiliate:state.affiliate,points_redeemed:state.points}}
async function calculate(){state.quote=state.cart.size?await api('/api/quote',cartData()):null;sessionStorage.setItem('glow_cart',JSON.stringify(cartData()))}
function totals(q){return `<div class="row"><span>Subtotal</span><span>${money(q.subtotal)}</span></div><div class="row"><span>Promo discount</span><span>−${money(q.coupon_discount??q.discount)}</span></div>${q.rewards_discount?`<div class="row"><span>Rewards (${q.points_redeemed} points)</span><span>−${money(q.rewards_discount)}</span></div>`:''}<div class="row"><span>Shipping</span><span>${money(q.shipping)}</span></div><div class="row"><span>Tax</span><span>${money(q.tax)}</span></div><div class="row total"><span>Total</span><span>${money(q.total)}</span></div>`}
async function loadStore(){state.catalog=await api('/api/catalog');renderMode(state.catalog.settings);try{state.customer=await api('/api/account')}catch{state.customer=null}const slug=decodeURIComponent(location.pathname.replace(/^\/store-next\/?/,'').replace(/\/$/,''));if(slug){try{state.affiliateProfile=await api('/api/storefronts/'+encodeURIComponent(slug));state.affiliate=state.affiliateProfile.slug;sessionStorage.setItem('glow_customer_store',state.affiliate);document.title=state.affiliateProfile.name+' · Glow GLP’s';document.querySelectorAll('header a[href="/store-next/"]').forEach(a=>a.setAttribute('href','/store-next/'+slug))}catch{app.innerHTML='<h1>Storefront unavailable</h1><a href="/store-next/">Visit the main store</a>';return}}const savedCart=sessionStorage.getItem('glow_cart');if(savedCart){try{const c=JSON.parse(savedCart);state.cart=new Map(c.items.filter(i=>Number.isInteger(i.id)&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=100&&state.catalog.products.some(p=>p.id===i.id&&p.stock>=i.quantity)).map(i=>[i.id,i.quantity]));state.coupon=typeof c.coupon==='string'?c.coupon:'';await calculate()}catch{state.cart.clear();state.coupon='';state.quote=null;sessionStorage.removeItem('glow_cart')}}const saved=sessionStorage.getItem('glow_order');if(saved){try{const d=JSON.parse(saved);state.order=await api('/api/orders/'+d.id,undefined,d.token);state.token=d.token;renderOrder();return}catch{sessionStorage.removeItem('glow_order')}}renderStore()}

function renderStore(){const a=state.affiliateProfile;app.innerHTML=`${a?`<section class="affiliate affiliate-heading">${a.photo_url?`<img class="affiliate-avatar" src="${esc(a.photo_url)}" alt="${esc(a.name)}">`:`<div class="affiliate-avatar avatar-placeholder" aria-hidden="true">${esc(a.name.trim().charAt(0).toUpperCase())}</div>`}<div><div class="eyebrow">Shopping with your Glow affiliate</div><h2>${esc(a.name)}’s Glow GLP’s Store</h2>${a.bio?`<p class="muted">${esc(a.bio)}</p>`:''}</div></section>`:''}<div class="intro"><div class="eyebrow">The research collection</div><h1>Your next order,<br>all in one place.</h1><p class="muted">Choose your materials, review your total, then submit your order. Payment and receipt upload follow your order confirmation.</p></div><div class="layout"><section><label class="search">Find a product<input id="search" type="search" placeholder="Search products"></label><div class="grid" id="products">${state.catalog.products.map(p=>`<article class="card" data-name="${esc(p.name.toLowerCase())}">${p.image?`<img class="product-image" src="${esc(p.image)}" alt="" loading="lazy">`:""}<span class="sku">${esc(p.sku)}</span><h3>${esc(p.name)}</h3><p class="stock">${p.stock} available</p><div class="bottom"><span class="price">${money(p.price)}</span><button data-action="add" data-id="${p.id}" ${p.stock===0?'disabled':''}>${p.stock?'Add to order':'Out of stock'}</button></div></article>`).join('')}</div></section><aside class="panel cart"><h2>Your order</h2>${state.cart.size?Array.from(state.cart,([id,qty])=>{const p=state.catalog.products.find(p=>p.id===id);return `<div class="line"><strong>${esc(p.name)}</strong><div class="row"><div class="qty"><button data-action="minus" data-id="${id}" aria-label="Remove one ${esc(p.name)}">−</button><span>${qty}</span><button data-action="plus" data-id="${id}" aria-label="Add one ${esc(p.name)}">+</button></div><span>${money(p.price*qty)}</span></div></div>`}).join(''):'<p class="muted">Your cart is ready when you are.</p>'}<div class="inline"><label>Coupon code<input id="coupon" value="${esc(state.coupon)}" placeholder="Enter promo code"></label>${button('Apply','coupon','secondary')}</div>${rewardsCart()}${state.quote?totals(state.quote):''}<div class="notice">${state.catalog.settings.demo!==false?'Preview checkout · do not send money.':'Pay after placing your order, then upload your payment screenshot for staff verification.'}</div>${button('Continue to checkout','checkout','full')}<p><small>Shipping is calculated after discounts. Points can be used with one promo code.</small></p></aside></div>`}
function checkout(){if(!state.cart.size){toast('Add a product first.');return}const preview=state.catalog.settings.demo!==false,labels={venmo:'Venmo',paypal:'PayPal',cashapp:'Cash App',zelle:'Zelle'},methods=Object.entries(labels).filter(([k])=>preview||state.catalog.settings.payment_links?.[k]);if(!methods.length){toast('Payment recipients are not configured yet.');return}app.innerHTML=`<div class="intro"><div class="eyebrow">${preview?'Preview checkout':'Checkout'}</div><h1>Let’s save your order.</h1><p class="muted">${preview?'Use fictional customer details. Do not send money.':'Confirm your shipping address and choose how you’ll pay. Payment instructions appear after you place your order.'} Keep your confirmation page; automatic confirmation emails are not enabled.</p></div><div class="layout"><form id="checkout" class="panel"><h2>Shipping details · United States</h2><div class="fields">${[['name','Full name','text','name'],['email','Email','email','email'],['address','Street address, including apartment or unit','text','shipping street-address'],['city','City','text','shipping address-level2'],['state','State / territory · two-letter code','text','shipping address-level1'],['zip','ZIP code','text','shipping postal-code']].map(([k,label,type,autocomplete])=>`<label class="${k==='address'?'wide':''}">${label}<input name="${k}" type="${type}" required maxlength="${k==='address'?500:k==='state'?2:k==='zip'?10:150}" autocomplete="${autocomplete}" ${k==='state'?'pattern="[A-Za-z]{2}"':k==='zip'?'pattern="[0-9]{5}(-[0-9]{4})?"':''} value="${esc(k==='email'?state.customer?.customer.email||'':k==='name'?state.customer?.customer.name||'':'')}" ${k==='email'&&state.customer?'readonly':''}></label>`).join('')}<label class="wide">Payment method<select name="payment_method">${methods.map(([k,label])=>`<option value="${k}">${label}</option>`).join('')}</select></label></div><div class="notice">Submitting reserves stock for 24 hours. Your payment screenshot keeps the order pending staff review.${preview?' This is a preview; do not send money.':''}</div><p id="checkout-error" class="error" role="alert"></p><div class="actions"><button type="submit">${preview?'Submit test order':'Place order'}</button>${button('Back to cart','back','secondary')}</div></form><aside class="panel"><h2>Order summary</h2>${state.quote.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.amount)}</span></div>`).join('')}${totals(state.quote)}${state.affiliate?`<p class="muted">Affiliate: ${esc(state.affiliate)}</p>`:''}</aside></div>`;document.querySelector('#checkout').dataset.key=crypto.randomUUID()}
function renderMode(settings){const preview=settings.demo!==false;const banner=document.querySelector('.demo');if(banner)banner.textContent=preview?'STORE PREVIEW · Test orders only · Do not send money':'GLOW LAB STORE · Pay using your chosen method after placing your order';const footer=document.querySelector('footer');if(footer)footer.textContent='Research materials are not for human or animal use.';if(!state.affiliate)document.title=preview?'Glow Lab · Store Preview':'Glow Lab · Store'}

function paymentInstructions(o,links,preview=false){const test=o.is_test!==false||preview,labels={venmo:'Venmo',paypal:'PayPal',cashapp:'Cash App',zelle:'Zelle'},payable=o.status==='awaiting_payment',recipient=links[o.payment_method]||'';return `<h2>Pay your order</h2><div class="row"><span>Amount to send</span><strong class="price">${money(o.total)}</strong></div><div class="row"><span>Order number</span><strong>${esc(o.id)}</strong></div><div class="row"><span>Payment method</span><strong>${esc(labels[o.payment_method]||o.payment_method)}</strong></div>${test?'<div class="notice">Preview only · Do not send money. Payment buttons are disabled for test orders.</div>':''}${payable?`<p>Send the exact total shown above. Include your order number in the payment note where available.</p>${recipient?o.payment_method==='zelle'?`<label>Zelle recipient<input readonly value="${esc(recipient)}"></label><p>Open your bank’s Zelle service, confirm the recipient, and enter the total. Zelle is paid through your bank.</p>`:test?`<button type="button" disabled>Open ${esc(labels[o.payment_method])} · preview only</button>`:`<a class="payment-link" href="${esc(recipient)}" target="_blank" rel="noopener noreferrer">Open ${esc(labels[o.payment_method])}</a><p class="muted">Confirm the recipient and enter the amount in the payment service. Return here after paying.</p>`:'<div class="notice">This payment method is not configured. Contact the store before sending payment.</div>'}`:o.status==='payment_submitted'?'<div class="notice">Your screenshot is awaiting review. Do not send another payment.</div>':['paid','shipped'].includes(o.status)?'<div class="notice">Payment verified. No further payment is needed.</div>':'<div class="notice">This order is closed. Do not send payment.</div>'}`}
function paymentPreview(){const links=state.admin.settings.payment_links;return `<section class="panel"><h2>Customer payment screen preview</h2><p class="muted">Sample order and amount. These previews never open payment services.</p><div class="grid">${['venmo','paypal','cashapp','zelle'].map(payment_method=>`<section class="card">${paymentInstructions({id:'PREVIEW-ORDER',total:12500,payment_method,status:'awaiting_payment',is_test:true},links,true)}</section>`).join('')}</div><p>After payment, customers attach a screenshot and transaction reference. Staff verify the actual funds before marking the order paid.</p></section>`}
function renderOrder(){const o=state.order;const test=o.is_test!==false;app.innerHTML=`<div class="intro"><div class="eyebrow">Order saved</div><h1>${esc(o.id)}</h1><p><span class="badge ${o.status}">${esc(o.status.replaceAll('_',' '))}</span></p><p class="muted">Keep this confirmation page to upload your screenshot and check order status.</p></div><div class="split"><section class="panel">${paymentInstructions(o,state.catalog?.settings.payment_links||{})}<div class="actions">${button('Copy amount','copy-amount','secondary')}${button('Copy order number','copy-order','secondary')}${button('Refresh status','refresh-order','secondary')}</div><p>Reservation ends: ${new Date(o.expires*1000).toLocaleString()}. Orders with a submitted receipt wait for staff review.</p><h3>Items</h3>${o.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.amount)}</span></div>`).join('')}${totals(o)}</section><section class="panel"><h2>${test?'Attach a test receipt':'Upload payment screenshot'}</h2><p class="muted">${test?'Upload a sample screenshot and reference. Do not send money.':'After paying, attach your screenshot and transaction reference. Staff will verify payment in the receiving account.'} Uploading does not mark the order paid.</p>${['awaiting_payment','payment_submitted'].includes(o.status)?`<form id="receipt"><label>Transaction reference<input name="reference" required maxlength="100" value="${esc(o.payment_reference||'')}" placeholder="${test?'DEMO-TRANSACTION-123':'Transaction ID or payment reference'}"></label><label>Screenshot · PNG, JPEG, or WebP, up to 3 MB<input name="screenshot" type="file" accept="image/png,image/jpeg,image/webp" required></label><button type="submit">${test?'Upload test receipt':'Submit payment screenshot'}</button><p class="error" id="receipt-error" role="alert"></p></form>`:`<p>This order no longer accepts receipt uploads.</p>`}${o.has_receipt?'<p>Receipt attached. Staff can view it securely in management.</p>':''}<div class="notice">Affiliate commission: ${o.commission_status==='eligible'?'eligible after verified payment':'not eligible until payment is verified'}. Affiliate credit is reviewed after payment verification.</div>${button(test?'Start another test order':'Start another order','new-order','secondary')}</section></div>`}
async function loadAdmin(){try{state.admin=await api('/api/admin/data');renderMode(state.admin.settings);renderAdmin()}catch{login()}}
function login(){app.innerHTML=`<div class="intro"><div class="eyebrow">Private management</div><h1>Your store workspace.</h1><p class="muted">Sign in with the password printed when the local server starts.</p></div><form id="login" class="panel login-panel"><label>Admin password<input name="password" type="password" autocomplete="current-password" required></label><button type="submit">Sign in</button><p id="login-error" class="error" role="alert"></p></form>`}
const field=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''}></label>`;
function renderAdmin(){const d=state.admin,live=d.orders.filter(o=>o.is_test===false),paid=live.filter(o=>['paid','shipped'].includes(o.status)),pending=live.filter(o=>['awaiting_payment','payment_submitted'].includes(o.status));app.innerHTML=`<div class="row"><div><div class="eyebrow">Glow GLP’s · management</div><h1>Store control, simplified.</h1></div>${button('Sign out','logout','secondary')}</div><div class="metrics">${[[live.length,'Live orders submitted'],[money(paid.reduce((n,o)=>n+o.total,0)),'Verified payments'],[money(pending.reduce((n,o)=>n+o.total,0)),'Awaiting payment or review'],[money(paid.reduce((n,o)=>n+o.commission,0)),'Eligible commission estimate']].map(([n,label])=>`<div class="panel metric"><strong>${n}</strong><small>${label}</small></div>`).join('')}</div><p class="muted">${d.orders.length-live.length} test orders excluded from sales totals · Checkout: ${d.settings.demo!==false?'preview':'live'}</p><div class="tabs" role="group" aria-label="Management views">${['orders','products','coupons','affiliates','customers','shipping','settings'].map(t=>`<button data-action="tab" data-tab="${t}" class="${t===state.tab?'selected':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><section id="admin-content">${adminContent()}</section>`}
function adminContent(){const d=state.admin;if(state.tab==='customers')return customersAdmin();if(state.tab==='shipping')return `<div class="panel"><h2>ShipStation preparation</h2><div class="notice">Nothing is sent to ShipStation yet. Verify an order’s payment, then review the proposed shipment data.</div>${d.orders.filter(o=>['paid','shipped'].includes(o.status)).map(o=>`<div class="row"><span>${esc(o.id)} · ${esc(o.customer.name)} · ${esc(o.shipstation_status)}</span><button data-action="shipment-preview" data-id="${o.id}">Review shipment</button></div>`).join('')||'<p>No paid orders ready yet.</p>'}<pre id="shipment-payload" class="payload"></pre></div>`;if(state.tab==='orders')return `<div class="panel tablewrap"><h2>Orders</h2><div class="fields"><label>Find an order<input id="order-search" type="search" value="${esc(state.orderSearch)}" placeholder="Order number, customer, email or affiliate"></label><label>Status<select id="order-status">${['all','awaiting_payment','payment_submitted','paid','shipped','canceled','expired'].map(v=>`<option value="${v}" ${state.orderStatus===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Order type<select id="order-mode">${['all','live','test'].map(v=>`<option value="${v}" ${state.orderMode===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="order-results">${orderRows()}</div></div><div id="detail"></div>`;
if(state.tab==='products')return `<div class="split"><section class="panel"><h2>Catalog</h2><p class="muted">Stock means units available after reservations.</p>${d.products.map(p=>`<div class="line"><div class="row"><strong>${esc(p.name)}</strong><button data-action="edit-product" data-id="${p.id}" class="secondary">Edit</button></div><small>${esc(p.sku)} · ${money(p.price)} · ${p.stock} available · ${p.active?'Active':'Hidden'}</small></div>`).join('')}</section><form id="product" class="panel"><h2 id="product-title">Add a product</h2><input name="id" type="hidden">${field('name','Product name')}${field('sku','Unique SKU')}${field('price','Selling price ($)',25,'number')}${field('stock','Available units',10,'number')}<label>Visibility<select name="active"><option value="1">Active</option><option value="0">Hidden</option></select></label><button type="submit">Save product</button><p class="error" role="alert"></p></form></div>`;
if(state.tab==='coupons')return `<div class="split"><section class="panel"><h2>Coupon codes</h2>${d.coupons.map(c=>`<div class="line"><div class="row"><strong>${esc(c.code)}</strong><button data-action="edit-coupon" data-code="${esc(c.code)}" class="secondary">Edit</button></div><small>${c.kind==='percent'?c.value+'%':money(c.value)} off · ${c.used}/${c.max_uses} uses reserved or paid · ${c.active?'Active':'Disabled'}</small></div>`).join('')}</section><form id="coupon-form" class="panel"><h2>Add or update a coupon</h2>${field('code','Code')}<label>Discount type<select name="kind"><option value="percent">Percentage</option><option value="fixed">Dollar amount off</option></select></label>${field('value','Percentage or dollar amount',20,'number')}${field('minimum','Minimum product subtotal ($)',0,'number')}${field('max_uses','Maximum uses',100,'number')}${field('expiry_date','Expiration (optional)','','date')}<label>Status<select name="active"><option value="1">Active</option><option value="0">Disabled</option></select></label><button type="submit">Save coupon</button><p class="error" role="alert"></p></form></div>`;
if(state.tab==='affiliates')return `${goaffproPanel()}<div class="split"><section class="panel"><h2>Personalized storefronts</h2><div id="photo-link-result" aria-live="polite"></div><div class="notice">Storefront attribution works. Verified live orders can be reported to GoAffPro. Test orders never create real commissions. Affiliate sign-in is still being built.</div>${d.affiliates.map(a=>`<div class="line"><div class="row"><strong>${esc(a.name)}</strong><div class="actions"><button data-action="copy-storefront" data-slug="${esc(a.slug)}" class="secondary">Copy store link</button><button data-action="photo-link" data-slug="${esc(a.slug)}" class="secondary" ${a.active?'':'disabled'}>Photo upload link</button><button data-action="edit-affiliate" data-slug="${esc(a.slug)}" class="secondary">Edit</button></div></div><p><a href="/store-next/${esc(a.slug)}" target="_blank" rel="noopener">/${esc(a.slug)}</a> · ${a.commission_bps/100}% estimate · ${a.active?'Active':'Disabled'}</p><small>${esc(a.bio)}</small></div>`).join('')}</section><form id="affiliate" class="panel"><h2 id="affiliate-title">Add or update an affiliate</h2><p class="muted">Imported storefront links stay fixed when you edit their name or introduction.</p>${field('slug','Store link slug (e.g. sarah)')}${field('name','Display name')}<label>Introduction<textarea name="bio" maxlength="500"></textarea></label>${field('goaffpro_id','GoAffPro affiliate ID (from your connection preview)')}${field('commission_bps','Commission basis points (1500 = 15%)',1500,'number')}<label>Status<select name="active"><option value="1">Active</option><option value="0">Disabled</option></select></label><button type="submit">Save affiliate</button><p class="error" role="alert"></p></form></div>`;
return `<form id="settings" class="panel"><h2>Shipping and payment recipients</h2><div class="notice">Saved recipients appear on the payment screen after an order is placed. Preview orders never open payment links.</div>${field('shipping_cents','Flat shipping ($)',d.settings.shipping_cents/100,'number')}${field('free_shipping_cents','Free shipping above discounted subtotal ($; 0 disables)',d.settings.free_shipping_cents/100,'number')}${field('venmo','Official Venmo HTTPS link',d.settings.payment_links.venmo)}${field('paypal','Official PayPal HTTPS link',d.settings.payment_links.paypal)}${field('cashapp','Official Cash App HTTPS link',d.settings.payment_links.cashapp)}${field('zelle','Zelle enrolled business email, phone, or tag',d.settings.payment_links.zelle)}<button type="submit">Save settings</button><p class="error" role="alert"></p><p class="muted">Customer accounts and rewards are built. Account setup links currently need manual email delivery. ShipStation is not connected; shipments need manual handling.</p></form>${checkoutSettings()}${paymentPreview()}`}
function orderRows(){const orders=state.admin.orders.filter(o=>(state.orderStatus==='all'||o.status===state.orderStatus)&&(state.orderMode==='all'||(state.orderMode==='live')===(o.is_test===false))&&[o.id,o.customer.name,o.customer.email,o.affiliate||''].join(' ').toLowerCase().includes(state.orderSearch.toLowerCase()));return orders.length?`<table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Affiliate</th><th>Review</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.id)}${o.is_test!==false?'<br><small>Test order</small>':''}</td><td>${esc(o.customer.name)}<br><small>${esc(o.customer.email)}</small></td><td>${money(o.total)}</td><td><span class="badge ${o.status}">${esc(o.status.replaceAll('_',' '))}</span></td><td>${esc(o.affiliate||'Direct')}</td><td><button data-action="order-detail" data-id="${o.id}">Open</button></td></tr>`).join('')}</tbody></table>`:'<p>No matching orders.</p>'}
function checkoutSettings(){const d=state.admin,stock=d.products.filter(p=>p.active&&p.stock>0).length,recipients=Object.values(d.settings.payment_links||{}).filter(Boolean).length;return `<form id="checkout-settings" class="panel account-ledger"><h2>Checkout mode</h2><p>${stock} active products in stock · ${recipients} payment recipients saved.</p><div class="notice">Live checkout accepts real orders, reserves inventory and rewards points, and displays your saved payment instructions. Staff must verify payment before points are earned or affiliate orders are reported. Sales tax will not be charged, matching your current checkout.</div><label>Mode<select name="mode"><option value="preview" ${d.settings.demo!==false?'selected':''}>Preview · test orders</option><option value="live" ${d.settings.demo===false?'selected':''}>Live · real orders</option></select></label><label><input name="tax_mode" type="checkbox" value="none" required ${d.settings.tax_mode==='none'?'checked':''}> Confirm this checkout charges no sales tax</label><button type="submit">Save checkout mode</button><p class="error" role="alert"></p><p class="muted">Before opening, save accurate stock and check each payment recipient. Automatic emails and ShipStation remain disconnected. GoAffPro’s first live sale still needs its reporting result checked.</p></form>`}
function goaffproPanel(){const g=state.admin.goaffpro||{},preview=state.goaffproPreview;return `<section class="panel integration-panel"><h2>GoAffPro connection</h2><p role="status">${g.verified?'Connection verified'+(g.checked_at?' · '+new Date(g.checked_at*1000).toLocaleString():''):g.configured?'Key configured · connection not yet verified':'Waiting for your GoAffPro access token in Netlify'}</p><p class="muted">${g.reporting_read_verified?'Order lookup and self-purchase read permissions checked.':'Check order reporting permissions before launch.'}</p><div class="actions">${button('Check GoAffPro connection','goaffpro-check','secondary')}${button('Check order reporting permissions','goaffpro-reporting-check','secondary')}<button type="button" data-action="create-storefronts" ${g.configured?'':'disabled'}>Create approved storefronts</button></div><p class="muted">Create a named store link for every approved affiliate. Existing links, custom introductions and disabled storefronts are preserved. GoAffPro determines commissions using your program rules. Verified live orders report automatically; test orders stay local.</p>${preview?`<div class="tablewrap"><table><thead><tr><th>Affiliate</th><th>GoAffPro ID</th><th>Referral code</th></tr></thead><tbody>${preview.affiliates.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.id)}</td><td>${esc(a.ref_code)}</td></tr>`).join('')}</tbody></table></div><p>${preview.affiliates.length} approved profiles returned${preview.has_more?' · more profiles are available':''}.</p>`:''}</section>`}
const storeUrl=slug=>(location.origin||'https://glowglps.com')+'/store-next/'+encodeURIComponent(slug);
async function importStorefronts(button){let offset=0,created=0,existing=0,skipped=0;const pages=new Set();for(let page=0;page<100;page++){button.textContent='Creating storefronts… '+created+' created';const result=await api('/api/admin/goaffpro/storefronts',{offset});const key=result.affiliates.map(a=>a.id).join(',');if(pages.has(key)&&result.affiliates.length)throw new Error('The affiliate list repeated a page. Created links are saved; please contact support before retrying.');pages.add(key);created+=result.imported.created;existing+=result.imported.existing;skipped+=result.imported.skipped;state.goaffproPreview=result;if(!result.has_more){await loadAdmin();toast(created+' storefronts created · '+existing+' already existed'+(skipped?' · '+skipped+' skipped':'')+'.');return}offset+=result.limit}throw new Error('The import reached its page limit. Created storefronts are saved.')}
async function profileApi(path,data){const opts={headers:{'X-Store-Request':'1','X-Profile-Token':state.profileToken}};if(data!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}const r=await fetch('/.netlify/functions/store-next?route='+encodeURIComponent('/affiliate-profile/'+state.profileSlug+path),opts);const result=await r.json();if(!r.ok)throw new Error(result.error||'Request failed');return result}
async function loadProfile(){state.profileSlug=decodeURIComponent(location.pathname.split('/').filter(Boolean).pop());const token=(location.hash||'').slice(1);if(token){state.profileToken=token;sessionStorage.setItem('glow_photo_'+state.profileSlug,token);history.replaceState(null,'',location.pathname)}else state.profileToken=sessionStorage.getItem('glow_photo_'+state.profileSlug)||'';try{renderProfile(await profileApi(''))}catch(e){app.innerHTML=`<h1>Photo upload link unavailable</h1><p class="error">${esc(e.message)}</p>`}}
function renderProfile(profile){app.innerHTML=`<section class="panel profile-panel"><div class="eyebrow">Your affiliate storefront</div><h1>Hi, ${esc(profile.name)}.</h1><p>Add a photo so customers recognize you on your Glow GLP’s store.</p>${profile.photo_url?`<img class="affiliate-avatar profile-avatar" src="${esc(profile.photo_url)}" alt="Your current photo">`:'<p>No photo uploaded yet.</p>'}<form id="affiliate-photo"><label>Your photo · JPEG, PNG, or WebP, up to 3 MB<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><p class="muted">Your photo will be cropped to a square. Choose one with your face near the center.</p><button type="submit">Save my photo</button><p class="error" role="alert"></p></form>${profile.photo_url?button('Remove my photo','remove-profile-photo','secondary'):''}<p><a href="${esc(storeUrl(profile.slug))}" target="_blank" rel="noopener">View my storefront</a></p><small>This private upload link changes only your photo. Keep it private.</small></section>`}

function detail(id){const o=state.admin.orders.find(o=>o.id===id);document.querySelector('#detail').innerHTML=`<section class="panel order"><h2>${esc(o.id)} · ${money(o.total)}${o.is_test!==false?' · Test order':''}</h2><p><span class="badge ${o.status}">${esc(o.status.replaceAll('_',' '))}</span></p><p>${esc(o.customer.name)} · ${esc(o.customer.email)}<br>${esc(o.customer.address)}, ${esc(o.customer.city)}, ${esc(o.customer.state)} ${esc(o.customer.zip)}</p>${o.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.amount)}</span></div>`).join('')}${totals(o)}<p>Method: ${esc(o.payment_method)} · Reference: ${esc(o.payment_reference||'Not submitted')}</p><p>Affiliate: ${esc(o.affiliate||'None')} · Estimated commission: ${money(o.commission)} (${o.commission_status.replaceAll('_',' ')})</p>${o.has_receipt?`<img class="receipt" src="/.netlify/functions/store-next?route=/admin/receipt/${o.id}" alt="Customer-uploaded payment receipt"><p class="muted">Verify against the actual account transaction before marking paid.</p>`:''}<div class="actions">${['awaiting_payment','payment_submitted'].includes(o.status)?`<button data-action="paid" data-id="${o.id}">Verify payment received</button><button data-action="cancel" data-id="${o.id}" class="danger">Cancel and release stock</button>`:''}${o.status==='paid'?`<label>Tracking number<input id="tracking"></label><button data-action="shipped" data-id="${o.id}">Mark shipped</button>`:''}</div>${['paid','shipped'].includes(o.status)&&o.affiliate?`<h3>GoAffPro reporting</h3><p>${esc((o.goaffpro_status||'not_ready').replaceAll('_',' '))}</p>${o.goaffpro_message?`<p class="muted">${esc(o.goaffpro_message)}</p>`:''}<div class="actions"><button data-action="goaffpro-preview" data-id="${o.id}" class="secondary">Preview affiliate report</button>${o.is_test===false?`<button data-action="goaffpro-report" data-id="${o.id}" class="secondary">${o.goaffpro_status==='needs_review'?'Check reporting status':'Report / check GoAffPro'}</button>`:'<span class="muted">Test order · no sale sent</span>'}</div><pre id="affiliate-report-preview" class="payload"></pre>`:''}${o.tracking?`<p>Tracking: ${esc(o.tracking)}</p>`:''}</section>`;document.querySelector('#detail').scrollIntoView({behavior:'smooth',block:'start'})}
function fill(form,values){for(const [k,v]of Object.entries(values))if(form.elements[k])form.elements[k].value=v??''}
document.addEventListener('input',e=>{if(e.target.id==='search')document.querySelectorAll('#products .card').forEach(c=>c.hidden=!c.dataset.name.includes(e.target.value.toLowerCase()))});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;b.disabled=true;try{if(['add','plus','minus'].includes(action)){const id=Number(b.dataset.id),old=state.cart.get(id)||0,newQty=old+(action==='minus'?-1:1);const p=state.catalog.products.find(p=>p.id===id);if(newQty>p.stock){toast('No more stock available.');return}if(newQty<=0)state.cart.delete(id);else state.cart.set(id,newQty);try{await calculate()}catch(err){if(old)state.cart.set(id,old);else state.cart.delete(id);throw err}renderStore()}
else if(action==='coupon'){const previous=state.coupon;state.coupon=document.querySelector('#coupon').value.trim();try{await calculate()}catch(err){state.coupon=previous;throw err}renderStore();toast('Coupon updated.')}
else if(action==='checkout'){await calculate();checkout()}
else if(action==='back')renderStore();
else if(action==='copy-amount'||action==='copy-order'){await navigator.clipboard.writeText(action==='copy-order'?state.order.id:(state.order.total/100).toFixed(2));toast('Copied.')}
else if(action==='refresh-order'){state.order=await api('/api/orders/'+state.order.id,undefined,state.token);renderOrder()}
else if(action==='new-order'){sessionStorage.removeItem('glow_cart');state.points=0;sessionStorage.removeItem('glow_order');state.order=null;state.token='';state.cart.clear();state.quote=null;state.coupon='';state.catalog=await api('/api/catalog');renderMode(state.catalog.settings);try{state.customer=await api('/api/account')}catch{state.customer=null}renderStore()}
else if(action==='apply-points'){const value=Number(document.querySelector('#use-points').value);if(!Number.isSafeInteger(value)||value<0)throw new Error('Enter a whole number of points.');const old=state.points;state.points=value;try{await calculate()}catch(e){state.points=old;throw e}renderStore()}
else if(action==='customer-logout'){await api('/api/account/logout',{});state.customer=null;state.points=0;renderAccountLogin();toast('Signed out.')}
else if(action==='account-order'){state.catalog=await api('/api/catalog');state.order=await api('/api/orders/'+b.dataset.id);state.token='';renderOrder()}
else if(action==='customer-setup-link'){const r=await api('/api/admin/customer/setup-link',{customer_id:b.dataset.id});const url=location.origin+'/store-next/account-setup#'+r.customer_id+'.'+r.token;const target=document.querySelector('#customer-link-result');target.innerHTML=`<div class="notice"><strong>Private account setup link</strong><p>Send this link only to <b>${esc(r.email)}</b> by email. Opening it lets the recipient set a password and access that customer’s points. It expires in 24 hours and replaces any prior setup link.</p><input id="customer-setup-link" readonly aria-label="Private customer setup link">${button('Copy setup link','copy-customer-link','secondary')}</div>`;target.querySelector('input').value=url;target.scrollIntoView({behavior:'smooth',block:'center'})}
else if(action==='copy-customer-link'){await navigator.clipboard.writeText(document.querySelector('#customer-setup-link').value);toast('Copied. Email it only to the customer address shown.')}
else if(action==='commit-rewards-import'){if(!state.migrationPreview||state.migrationPreview.conflicts.length)throw new Error('Resolve migration conflicts first.');const r=await api('/api/admin/rewards/import',{batch_id:state.migrationPreview.batch_id});state.migrationPreview=null;state.customerAdmin=await api('/api/admin/customers');renderAdmin();toast(r.added+' balances imported · '+r.existing+' already existed · '+r.held+' held for review.')}
else if(action==='customer-ledger'){const a=state.customerAdmin.customers.find(a=>a.id===b.dataset.id),target=document.querySelector('#customer-ledger');target.innerHTML=`<section class="panel"><h2>${esc(a.name)} · points history</h2>${ledgerTable(state.customerAdmin.ledger.filter(e=>e.customer_id===a.id))}<form id="rewards-adjust" data-key="${crypto.randomUUID()}"><input name="customer_id" type="hidden" value="${esc(a.id)}"><label>Adjustment · positive to add, negative to subtract<input name="points" type="number" step="1" required></label><label>Reason<input name="note" maxlength="500" required></label><button type="submit">Save points adjustment</button><p class="error" role="alert"></p></form><p class="muted">Adjustments are recorded in the ledger. Negative adjustments can leave a balance owing; future earnings offset it. Refunds and GoAffPro reversals still need separate staff handling.</p></section>`;target.scrollIntoView({behavior:'smooth'})}
else if(action==='goaffpro-check'){state.goaffproPreview=null;const result=await api('/api/admin/goaffpro/check',{});state.goaffproPreview=result;await loadAdmin();toast('GoAffPro connection verified.')}
else if(action==='goaffpro-reporting-check'){const r=await api('/api/admin/goaffpro/reporting-check',{});await loadAdmin();toast(r.message)}
else if(action==='goaffpro-report'){const r=await api('/api/admin/goaffpro/report',{id:b.dataset.id});await loadAdmin();detail(b.dataset.id);toast(r.message||('GoAffPro: '+r.status))}
else if(action==='goaffpro-preview'){const r=await api('/api/admin/goaffpro/preview',{id:b.dataset.id});document.querySelector('#affiliate-report-preview').textContent=JSON.stringify(r,null,2)}
else if(action==='tab'){state.tab=b.dataset.tab;if(state.tab==='customers')state.customerAdmin=await api('/api/admin/customers');renderAdmin()}
else if(action==='logout'){await api('/api/admin/logout',{});state.goaffproPreview=null;state.admin=null;login()}
else if(action==='shipment-preview'){const result=await api('/api/admin/shipment-preview',{id:b.dataset.id});document.querySelector('#shipment-payload').textContent=JSON.stringify(result,null,2)}else if(action==='order-detail')detail(b.dataset.id);
else if(action==='edit-product'){(()=>{const p=state.admin.products.find(p=>p.id===Number(b.dataset.id));fill(document.querySelector('#product'),{...p,price:p.price/100})})();document.querySelector('#product-title').textContent='Edit product'}
else if(action==='edit-coupon'){const c=state.admin.coupons.find(c=>c.code===b.dataset.code);fill(document.querySelector('#coupon-form'),{...c,value:c.kind==='fixed'?c.value/100:c.value,minimum:c.minimum/100,expiry_date:c.expires?new Date(c.expires*1000).toISOString().slice(0,10):''})}
else if(action==='edit-affiliate'){const form=document.querySelector('#affiliate');fill(form,state.admin.affiliates.find(a=>a.slug===b.dataset.slug));form.elements.slug.readOnly=true;document.querySelector('#affiliate-title').textContent='Edit storefront';form.scrollIntoView({behavior:'smooth',block:'start'})}
else if(action==='copy-storefront'){await navigator.clipboard.writeText(storeUrl(b.dataset.slug));toast('Storefront link copied.')}
else if(action==='create-storefronts')await importStorefronts(b);
else if(action==='photo-link'){const r=await api('/api/admin/affiliate/photo-link',{slug:b.dataset.slug});const url=(location.origin||'https://glowglps.com')+'/store-next/profile/'+encodeURIComponent(r.slug)+'#'+r.token;const target=document.querySelector('#photo-link-result');target.innerHTML=`<div class="notice"><strong>Private photo upload link</strong><input id="private-photo-link" type="text" readonly aria-label="Private photo upload link"><p>Share this link only with this affiliate. It expires in 30 days; creating a new link replaces their previous one.</p>${button('Copy private upload link','copy-photo-link','secondary')}</div>`;target.querySelector('input').value=url;target.scrollIntoView({behavior:'smooth',block:'center'})}
else if(action==='copy-photo-link'){await navigator.clipboard.writeText(document.querySelector('#private-photo-link').value);toast('Private photo upload link copied.')}
else if(action==='remove-profile-photo'){await profileApi('/photo',{remove:true});renderProfile(await profileApi(''));toast('Photo removed.')}
else if(['paid','cancel','shipped'].includes(action)){const status=action==='cancel'?'canceled':action;if(!confirm(action==='paid'?'Have you verified this exact payment in the receiving account?':action==='cancel'?'Cancel this order and release reserved stock?':'Mark this order shipped?'))return;await api('/api/admin/status',{id:b.dataset.id,status,verified:action==='paid',tracking:document.querySelector('#tracking')?.value||''});await loadAdmin();detail(b.dataset.id);toast(action==='paid'?'Payment saved. GoAffPro status appears below.':'Order updated.')}
}catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target;e.preventDefault();const submit=f.querySelector('[type=submit]');submit.disabled=true;const err=f.querySelector('.error');if(err)err.textContent='';try{const values=Object.fromEntries(new FormData(f));if(f.id==='login'){await api('/api/admin/login',values);await loadAdmin()}
else if(f.id==='customer-register'){const r=await api('/api/account/register',values);f.innerHTML=`<p role="status">${esc(r.message)}</p>`}
else if(f.id==='customer-login'){state.customer=await api('/api/account/login',values);renderAccount()}
else if(f.id==='customer-setup'){if(values.password!==values.confirm_password)throw new Error('Passwords must match.');state.customer=await api('/api/account/setup',{customer_id:state.setupId,token:state.setupToken,password:values.password});state.setupToken='';history.replaceState(null,'','/store-next/account');renderAccount();toast('Your account is ready.')}
else if(f.id==='rewards-import'){const file=f.elements.migration.files[0];if(!file||file.size>2*1024*1024)throw new Error('Choose the migration JSON file, up to 2 MB.');let data;try{data=JSON.parse(await file.text())}catch{throw new Error('Choose a valid JSON migration file.')}state.migrationPreview=await api('/api/admin/rewards/import-preview',{customers:data.customers});renderAdmin()}
else if(f.id==='rewards-adjust'){await api('/api/admin/rewards/adjust',{...values,points:Number(values.points),idempotency_key:f.dataset.key});state.customerAdmin=await api('/api/admin/customers');renderAdmin();toast('Points adjustment recorded.')}
else if(f.id==='checkout'){const customer={...values};delete customer.payment_method;const result=await api('/api/orders',{...cartData(),customer,payment_method:values.payment_method,idempotency_key:f.dataset.key});state.order=result.order;state.token=result.token;sessionStorage.removeItem('glow_cart');sessionStorage.setItem('glow_order',JSON.stringify({id:result.order.id,token:result.token}));renderOrder()}
else if(f.id==='receipt'){const file=f.elements.screenshot.files[0];if(!file||file.size>3*1024*1024)throw new Error('Choose a screenshot under 3 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});state.order=await api('/api/orders/'+state.order.id+'/receipt',{file:data,mime:file.type,reference:values.reference},state.token);renderOrder();toast('Receipt attached; awaiting verification.')}
else if(f.id==='affiliate-photo'){const file=f.elements.photo.files[0];if(!file||file.size>3*1024*1024)throw new Error('Choose a photo up to 3 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Could not read this photo.'));reader.readAsDataURL(file)});await profileApi('/photo',{file:data,mime:file.type});renderProfile(await profileApi(''));toast('Your storefront photo has been saved.')}
else if(f.id==='product'){for(const k of ['price','stock','active'])values[k]=Number(values[k]);values.price=Math.round(values.price*100);if(values.id)values.id=Number(values.id);await api('/api/admin/product',values);await loadAdmin();toast('Product saved.')}
else if(f.id==='coupon-form'){for(const k of ['value','minimum','max_uses','active'])values[k]=Number(values[k]);values.minimum=Math.round(values.minimum*100);if(values.kind==='fixed')values.value=Math.round(values.value*100);values.expires=values.expiry_date?Math.floor(new Date(values.expiry_date+'T23:59:59').getTime()/1000):0;await api('/api/admin/coupon',values);await loadAdmin();toast('Coupon saved.')}
else if(f.id==='affiliate'){values.commission_bps=Number(values.commission_bps);values.active=Number(values.active);await api('/api/admin/affiliate',values);await loadAdmin();toast('Affiliate saved.')}
else if(f.id==='checkout-settings'){await api('/api/admin/checkout-settings',values);await loadAdmin();toast('Checkout mode saved.')}
else if(f.id==='settings'){await api('/api/admin/settings',{shipping_cents:Math.round(Number(values.shipping_cents)*100),free_shipping_cents:Math.round(Number(values.free_shipping_cents)*100),payment_links:Object.fromEntries(['venmo','paypal','cashapp','zelle'].map(k=>[k,values[k]]))});await loadAdmin();toast('Settings saved.')}
}catch(error){if(err)err.textContent=error.message;else toast(error.message)}finally{submit.disabled=false}});
function rewardsCart(){if(!state.customer)return `<p><a href="/store-next/account">Sign in to view your rewards</a></p>`;const w=state.customer.wallet;return `<div class="notice"><strong>${w.available} points available · ${money(w.value_cents)}</strong><p>1 point per $1 of products after discounts. 100 points = $5 off. Points work with one promo code and never expire.</p>${state.catalog.settings.demo?'<p>Test orders do not earn or spend real points.</p>':`<label>Points to use<input id="use-points" type="number" min="0" max="${w.available}" step="1" value="${state.points}"></label>${button('Apply points','apply-points','secondary')}`}</div>`}
function accountStoreUrl(){const slug=sessionStorage.getItem('glow_customer_store')||'';return /^[a-z0-9-]+$/.test(slug)?storeUrl(slug):'/store-next/'}
function ledgerTable(entries){return entries.length?`<div class="tablewrap"><table><thead><tr><th>Date</th><th>Activity</th><th>Points</th><th>Held change</th><th>Balance</th><th>Order / note</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.created*1000).toLocaleString()}</td><td>${esc(e.kind.replaceAll('_',' '))}</td><td>${e.points>0?'+':''}${e.points}</td><td>${e.reserved_delta>0?'+':''}${e.reserved_delta}</td><td>${e.balance_after}</td><td>${esc(e.order_id||e.note)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No points transactions yet.</p>'}
async function loadAccount(){try{state.customer=await api('/api/account');renderAccount()}catch{state.customer=null;renderAccountLogin()}}
function renderAccountLogin(){app.innerHTML=`<div class="intro"><div class="eyebrow">Your Glow Lab account</div><h1>Your orders. Your rewards.</h1><p class="muted">Earn 1 point per $1 of products after discounts, excluding shipping and tax. 100 points = $5 off. Points never expire.</p></div><div class="split"><form id="customer-login" class="panel"><h2>Sign in</h2><label>Email<input name="email" type="email" autocomplete="username" required maxlength="150"></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button type="submit">Sign in</button><p class="error" role="alert"></p><p class="muted">Forgot your password? Contact the store for a private reset link sent to your account email.</p></form><form id="customer-register" class="panel"><h2>Request an account</h2><label>Name<input name="name" autocomplete="name" required maxlength="150"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="150"></label><button type="submit">Request account setup</button><p class="error" role="alert"></p><p class="muted">Staff will provide a private setup link to your email. Automatic email delivery is not enabled yet. Use the same email as your previous orders to claim a migrated balance after verification.</p></form></div><p><a href="${esc(accountStoreUrl())}">Back to the store</a></p>`}
function renderAccount(){const d=state.customer,w=d.wallet;app.innerHTML=`<div class="row"><div><div class="eyebrow">Your customer account</div><h1>Hi, ${esc(d.customer.name)}.</h1><p class="muted">${esc(d.customer.email)}</p></div>${button('Sign out','customer-logout','secondary')}</div><div class="metrics"><section class="panel metric"><strong>${w.available}</strong><small>Available points</small></section><section class="panel metric"><strong>${money(w.value_cents)}</strong><small>Available discount</small></section><section class="panel metric"><strong>${w.reserved}</strong><small>Points held for unpaid orders</small></section><section class="panel metric"><strong>${w.balance}</strong><small>Total points balance</small></section></div><div class="notice">Points never expire and can be used with one promo code. Earn 1 point for each whole $1 of products after all discounts, excluding shipping and tax. Each point is worth $0.05. Earned points appear after staff verify payment; test orders do not change your real balance.</div><section class="panel"><h2>Your orders</h2>${d.orders.map(o=>`<div class="row"><span>${esc(o.id)} · ${money(o.total)} · ${esc(o.status.replaceAll('_',' '))}${o.is_test!==false?' · Test order':''}</span><button data-action="account-order" data-id="${esc(o.id)}" class="secondary">View order</button></div>`).join('')||'<p>No orders associated with this account yet.</p>'}<p class="muted">Earlier guest orders are not linked by email alone.</p></section><section class="panel account-ledger"><h2>Your points history</h2>${ledgerTable(d.ledger)}</section><p><a href="${esc(accountStoreUrl())}">Continue shopping</a></p>`}
function loadAccountSetup(){const parts=location.hash.slice(1).split('.');state.setupId=parts[0]||'';state.setupToken=parts[1]||'';history.replaceState(null,'',location.pathname);if(!/^[a-f0-9]{64}$/.test(state.setupId)||!/^[A-Za-z0-9_-]{43}$/.test(state.setupToken)){app.innerHTML='<h1>Account setup link unavailable</h1><p>Contact the store for a new private setup link.</p>';return}app.innerHTML=`<form id="customer-setup" class="panel login-panel"><div class="eyebrow">Private account setup</div><h1>Choose your password.</h1><p>Use a passphrase with 15–128 characters. Completing this private setup verifies the email account the link was sent to.</p><label>New password<input name="password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label>Confirm password<input name="confirm_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><button type="submit">Save password and sign in</button><p class="error" role="alert"></p><p class="muted">This link works once and expires after 24 hours. Reloading this page clears the link; reopen the original link if needed.</p></form>`}
function customersAdmin(){const d=state.customerAdmin,p=state.migrationPreview;if(!d)return '<p>Open Customers to load account and rewards records.</p>';return `<section class="panel"><h2>Customer accounts and rewards</h2><div class="notice">1 point per whole $1 of products after all discounts, excluding shipping and tax. Each point is worth $0.05. Points stack with one promo code and never expire. Membership levels are inactive.</div><p>Automatic email delivery is not enabled. Create a private setup / reset link and email it only to the customer address shown. The customer chooses their password; completing setup claims any matching imported balance.</p><div id="customer-link-result" aria-live="polite"></div><div class="tablewrap"><table><thead><tr><th>Customer</th><th>Email</th><th>Status</th><th>Available points</th><th>Actions</th></tr></thead><tbody>${d.customers.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.email)}</td><td>${a.verified?'Verified':'Awaiting email setup'}</td><td>${a.wallet.available} · ${money(a.wallet.value_cents)}</td><td><div class="actions"><button data-action="customer-setup-link" data-id="${a.id}" class="secondary">${a.verified?'Password reset link':'Account setup link'}</button>${a.verified?`<button data-action="customer-ledger" data-id="${a.id}" class="secondary">Points history / adjustment</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${!d.customers.length?'<p>No account requests yet. Customers can request setup at <a href="/store-next/account">the account page</a>.</p>':''}</section><div id="customer-ledger"></div><section class="panel account-ledger"><h2>Carry over WooCommerce balances</h2><p>Upload the saved migration JSON. Preview totals first, then import. Repeating the same file does not add points twice. Changed balances require review. Imported balances stay unclaimed until email setup is completed.</p><form id="rewards-import"><label>Migration JSON file · up to 2 MB<input name="migration" type="file" accept="application/json,.json" required></label><button type="submit">Preview balances</button><p class="error" role="alert"></p></form>${p?`<div class="notice"><strong>${p.count} rows · ${p.points_total} points · ${money(p.points_total*5)}</strong><p>${p.existing_count} already imported · ${p.held.length} held for email review · ${p.missing_redeem_history} missing historical redeemed value.</p>${p.held.map(r=>`<p>${esc(r.email)} — ${esc(r.reason)}</p>`).join('')}${p.conflicts.length?`<p class="error">Conflicting existing balances: ${p.conflicts.map(esc).join(', ')}</p>`:button('Import these balances','commit-rewards-import') }</div>`:''}<h3>${d.imports.length} imported balances</h3><p>${d.imports.filter(r=>r.claimed).length} claimed · ${d.imports.filter(r=>r.held).length} held for review</p><div class="tablewrap"><table><thead><tr><th>Email</th><th>Points</th><th>Redeemed history</th><th>Status</th></tr></thead><tbody>${d.imports.map(r=>`<tr><td>${esc(r.email)}</td><td>${r.points}</td><td>${r.redeem_points===null?'Missing':r.redeem_points}</td><td>${r.held?'Held for email review':r.claimed?'Claimed':'Awaiting verified account'}</td></tr>`).join('')}</tbody></table></div></section>`}
if(/\/store-next\/(account(?:-setup)?|profile\/[a-z0-9-]+)\/?$/.test(location.pathname))api('/api/catalog').then(d=>renderMode(d.settings)).catch(()=>{});
(/\/store-next\/account-setup\/?$/.test(location.pathname)?Promise.resolve(loadAccountSetup()):/\/store-next\/account\/?$/.test(location.pathname)?loadAccount():/\/store-next\/profile\/[a-z0-9-]+\/?$/.test(location.pathname)?loadProfile():/\/store-next\/admin\/?$/.test(location.pathname)?loadAdmin():loadStore()).catch(err=>{app.innerHTML=`<h1>Unable to load the store</h1><p class="error">${esc(err.message)}</p>`});

document.addEventListener('input',e=>{if(e.target.id==='order-search'){state.orderSearch=e.target.value;document.querySelector('#order-results').innerHTML=orderRows()}});
document.addEventListener('change',e=>{if(['order-status','order-mode'].includes(e.target.id)){state[e.target.id==='order-status'?'orderStatus':'orderMode']=e.target.value;document.querySelector('#order-results').innerHTML=orderRows()}});
